async function ensureProgressFromListings(){const b=bridge();if(!b?.DB)return progressState(await get(PROGRESS_KEY,{}));const state=progressState(await get(PROGRESS_KEY,{})),seen=new Set(state.confirmedPosts.map(x=>x.key)),myName=String(await get('userName','')),rows=await b.DB.all('listings'),added=[];for(const row of rows){if(!row?.postedAt||!validFacebookUrl(row.facebookUrl)||row.ownerUserName&&!same(row.ownerUserName,myName))continue;const key=facebookPostKey(row);if(!key||seen.has(key))continue;seen.add(key);added.push({key,listingId:String(row.id||''),vehicleId:String(row.vehicleId||''),facebookUrl:String(row.facebookUrl||''),postedAt:row.postedAt,confirmedAt:new Date().toISOString(),source:'Existing saved LotKeys Listing'})}if(!added.length)return state;const next=progressState({...state,confirmedPosts:[...state.confirmedPosts,...added],updatedAt:new Date().toISOString()});await set(PROGRESS_KEY,next);const imported=await importCurrentStoreAwards(),profile=imported.profile;await storeProfileForCurrent(imported.entries,next,profile);queueAccountSync();return next}
